+
+            // Fill with a non-zero value
+            int value = randomBoolean() ? randomIntBetween(Integer.MIN_VALUE, -1) : randomIntBetween(1, Integer.MAX_VALUE);
+            for (int i = 0; i < initialSize; i++) {
